assert.equal(a.balance('x'),23); assert.equal(a.balance('y'),11); assert.equal(b.balance('x'),29);
console.log('R5: accumulation, other customer and independent ledger PASS');
const app=readFileSync('src/loyalty/application/award-points.ts','utf8');
assert(!/process\.|NODE_ENV|test|alice|4250|double-points/.test(app+domain));
